/*
 * network_$send_request - build and transmit a request to a partner node
 *
 * Original address: 0x00E0F5F4 (module-local; the SAU2 map has no symbol
 * here; was Ghidra network_$send_request)
 * Size: 336 bytes (0x00E0F5F4 .. 0x00E0F743), then the word 0 at 0x00E0F744
 * Generated by: Claude Opus 5.5
 *
 * Runs on its callers' A5 = 0xE248FC (the NETWORK_ data segment).
 * Frame (link.w A6,-0x1c): arguments as in network/network_internal.h;
 * (-0x18) port, (-0x16) header length, (-0x14) header VA, (-0xc) header PA,
 * (-0x8) the NET_IO_$SEND info record.  D2w counts transmit retries.
 *
 * Blocks:
 *   0x00E0F608-0x00E0F616  retries = 0; D6 = &net_handle[1] (the node)
 *   0x00E0F618-0x00E0F626  NETWORK_$GETHDR(&node, &hdr_va, &hdr_pa)
 *   0x00E0F62A-0x00E0F678  PKT_$BLD_INTERNET_HDR(net_handle[0], node, 1, -1,
 *                          NODE_$ME, sock, &NETWORK_$REQUEST_PKT_INFO, id,
 *                          cmd, cmd_len, data_len, &port, hdr, &hdr_len,
 *                          retry_out, timeout_out, status)
 *   0x00E0F67C-0x00E0F688  failed -> NETWORK_$RTNHDR(&hdr_va), return
 *   0x00E0F68C-0x00E0F6C2  NET_IO_$SEND(port, &hdr_va, hdr_pa, hdr_len, 0,
 *                          &data_pa, data_len, NETWORK_$REQUEST_SEND_FLAGS,
 *                          &info, status); NETWORK_$RTNHDR(&hdr_va)
 *   0x00E0F6C4-0x00E0F6CE  ok or parity error during transmit -> return
 *   0x00E0F6D0-0x00E0F706  info.port_net == 0: xmit_status 0x2000 to a node
 *                          other than the mother node -> too many retries;
 *                          bits 10, 2, 6 or 5 -> status = ok, return
 *   0x00E0F708-0x00E0F71A  ++retries > *retry_out (unsigned) and not the
 *                          mother node -> too many retries
 *   0x00E0F71C-0x00E0F730  TIME_$WAIT(&0 (0x00E0F744), &NETWORK_$RETRY_DELAY,
 *                          status); go round again (a new header each time)
 */

#include "network/network_internal.h"
#include "net_io/net_io.h"
#include "time/time.h"

/* pea (0x20,PC) at 0x00E0F722 = 0x00E0F744: the word 0, TIME_$WAIT's
 * relative delay type (`gsk read 0xE0F744 2` = 00 00). */
static const uint16_t network_$c_relative = 0x0000;

void network_$send_request(void *net_handle, int16_t sock_num, int16_t pkt_id,
                           int16_t *cmd_buf, int16_t cmd_len, uint32_t data_pa,
                           uint16_t data_len, uint16_t *retry_out,
                           int16_t *timeout_out, status_$t *status_ret)
{
    uint32_t *net = (uint32_t *)net_handle;     /* A4 */
    uint32_t *node_p;                           /* D6 */
    uint16_t retries;                           /* D2w */
    int16_t port;                               /* (-0x18,A6) */
    uint16_t hdr_len;                           /* (-0x16,A6) */
    uint32_t hdr_va;                            /* (-0x14,A6) */
    uint32_t hdr_pa;                            /* (-0xc,A6) */
    net_io_$send_info_t info;                   /* (-0x8,A6) */

    /* 0x00E0F608-0x00E0F616 */
    retries = 0;
    node_p = &net[1];

    for (;;) {
        /* 0x00E0F618-0x00E0F626 */
        NETWORK_$GETHDR(node_p, &hdr_va, &hdr_pa);

        /* 0x00E0F62A-0x00E0F678 */
        PKT_$BLD_INTERNET_HDR(net[0], *node_p, 1, -1, NODE_$ME,
                              (uint16_t)sock_num, &NETWORK_$REQUEST_PKT_INFO,
                              (uint16_t)pkt_id, cmd_buf, (uint16_t)cmd_len,
                              data_len, &port,
                              (pkt_$hdr_t *)ARCH_VA_TO_PTR(hdr_va), &hdr_len,
                              retry_out, (uint16_t *)timeout_out, status_ret);

        /* 0x00E0F67C-0x00E0F688 */
        if (*status_ret != status_$ok) {
            NETWORK_$RTNHDR(&hdr_va);
            return;
        }

        /* 0x00E0F68C-0x00E0F6C2 */
        NET_IO_$SEND(port, &hdr_va, hdr_pa, hdr_len, 0, &data_pa,
                     (int16_t)data_len, NETWORK_$REQUEST_SEND_FLAGS, &info,
                     status_ret);
        NETWORK_$RTNHDR(&hdr_va);

        /* 0x00E0F6C4-0x00E0F6CE */
        if (*status_ret == status_$ok ||
            *status_ret == status_$network_memory_parity_error_during_transmit) {
            return;
        }

        /* 0x00E0F6D0-0x00E0F706 */
        if (info.port_net == 0) {
            if (info.xmit_status == 0x2000 &&
                *node_p != NETWORK_$MOTHER_NODE) {
                *status_ret = status_$network_too_many_transmit_retries;
                return;
            }
            if ((info.xmit_status & 0x0400) != 0 ||
                (info.xmit_status & 0x0004) != 0 ||
                (info.xmit_status & 0x0040) != 0 ||
                (info.xmit_status & 0x0020) != 0) {
                *status_ret = status_$ok;           /* 0x00E0F704 */
                return;
            }
        }

        /* 0x00E0F708-0x00E0F71A: cmp.w / bls, unsigned */
        retries++;
        if (retries > *retry_out && *node_p != NETWORK_$MOTHER_NODE) {
            *status_ret = status_$network_too_many_transmit_retries;
            return;
        }

        /* 0x00E0F71C-0x00E0F730 */
        TIME_$WAIT((uint16_t *)&network_$c_relative, &NETWORK_$RETRY_DELAY,
                   status_ret);
    }
}
